<script setup lang="ts">
import {computed} from 'vue';import type {EChartsCoreOption} from 'echarts/core';import ChartCanvas from '../../Operation/components/ChartCanvas.vue';import type {RiskPrediction} from '../../../types/risk';import type {FloodHistoryPoint} from '../../../types/flood';
const props=defineProps<{prediction:RiskPrediction|null;history:FloodHistoryPoint[]}>();
const metrics=[{key:'waterLevel' as const,title:'水位：观测与未来',unit:'cm'},{key:'riskScore' as const,title:'风险：观测与未来',unit:'分'}];
const options=computed(()=>metrics.map(m=>{const p=props.prediction;const now=props.history.at(-1)?.time??p?.simulationTime??0;return {animation:false,tooltip:{trigger:'axis'},grid:{left:48,right:20,top:30,bottom:35},xAxis:{type:'value',name:'min',axisLabel:{color:'#91acba'},splitLine:{show:false}},yAxis:{type:'value',name:m.unit,min:0,...(m.key==='riskScore'?{max:100}:{}),axisLabel:{color:'#91acba'},splitLine:{lineStyle:{color:'#244050'}}},series:[{name:'仿真观测',type:'line',showSymbol:false,lineStyle:{color:'#8fbcc9',width:2},data:props.history.filter(x=>x.time>=now-1800).map(x=>[x.time/60,x[m.key]])},...(['physicalForecast','mlForecast'] as const).map((key,index)=>({name:index?'XGBoost 预测':'物理模型预测',type:'line',showSymbol:true,symbolSize:6,lineStyle:{type:index?'dotted':'dashed',width:2,color:index?'#e7b46b':'#61c9df'},itemStyle:{color:index?'#e7b46b':'#61c9df'},data:p&&p[key].length?[[p.simulationTime/60,p.current[m.key]],...p[key].map(x=>[p.simulationTime/60+x.minute,x[m.key]])]:[]}))]} as EChartsCoreOption;}));
</script><template><section class="risk-charts" data-testid="risk-charts"><article v-for="(m,i) in metrics" :key="m.key" class="panel"><header><h3>{{m.title}}</h3><small>过去30仿真分钟 / 未来30分钟</small></header><div class="risk-chart-key"><span>— 仿真观测</span><span>┄ 物理预测</span><span>┈ XGBoost预测</span></div><ChartCanvas :option="options[i]!" :label="m.title"/></article></section></template>
